import{_ as t,o,c as n,a2 as a}from"./chunks/framework.CPzUcv0I.js";const h=JSON.parse('{"title":"Getting Started with Gens Launcher","description":"","frontmatter":{},"headers":[],"relativePath":"guide/players/getting-started.md","filePath":"guide/players/getting-started.md"}'),r={name:"guide/players/getting-started.md"};function i(s,e,l,c,d,g){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="getting-started-with-gens-launcher" tabindex="-1">Getting Started with Gens Launcher <a class="header-anchor" href="#getting-started-with-gens-launcher" aria-label="Permalink to &quot;Getting Started with Gens Launcher&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Minecraft-Vanilla%20%26%20Modded-green.svg" alt="Minecraft"><img src="https://img.shields.io/badge/Platform-Windows%20%7C%20macOS%20%7C%20Linux-blue.svg" alt="Platforms"><img src="https://img.shields.io/badge/License-MIT-orange.svg" alt="License"></div><p>Welcome to the official documentation of <strong>Gens Launcher</strong>. This guide walks you step-by-step through discovering the launcher, connecting your Minecraft account, and launching your first gaming session.</p><hr><h2 id="why-gens-launcher" tabindex="-1">Why Gens Launcher? <a class="header-anchor" href="#why-gens-launcher" aria-label="Permalink to &quot;Why Gens Launcher?&quot;">​</a></h2><p>Gens Launcher was engineered from the ground up to combine <strong>maximum performance</strong>, <strong>sleek modern ergonomics</strong>, and <strong>uncompromising security</strong>:</p><ul><li><strong>Lightweight and Blazing Fast:</strong> Built with zero unnecessary third-party bloatware, the launcher boots instantly and consumes negligible system memory.</li><li><strong>Multi-Modloader Freedom:</strong> Seamlessly create and play <strong>Vanilla</strong>, <strong>Fabric</strong>, <strong>Forge</strong>, <strong>Quilt</strong>, or <strong>NeoForge</strong> profiles in just a few clicks.</li><li><strong>Horizon Cloud Sync:</strong> Powered by the companion <strong>Gens-Horizon</strong> engine, automatically back up and sync your worlds, options, and mods with Google Drive, Dropbox, or OneDrive.</li><li><strong>Integrated Content Catalog:</strong> Search and install mods, resource packs, and shaders directly from Modrinth and CurseForge without ever leaving the launcher.</li><li><strong>100% Privacy Focused:</strong> Free and open-source under the MIT license, with zero corporate telemetry or tracking.</li></ul><hr><h2 id="logging-in-to-your-minecraft-account" tabindex="-1">Logging In to Your Minecraft Account <a class="header-anchor" href="#logging-in-to-your-minecraft-account" aria-label="Permalink to &quot;Logging In to Your Minecraft Account&quot;">​</a></h2><p>Gens Launcher supports two modes of authentication:</p><h3 id="_1-official-microsoft-account-recommended" tabindex="-1">1. Official Microsoft Account (Recommended) <a class="header-anchor" href="#_1-official-microsoft-account-recommended" aria-label="Permalink to &quot;1. Official Microsoft Account (Recommended)&quot;">​</a></h3><ol><li>Click the <strong>Log In with Microsoft</strong> button located in the top-right corner of the home screen.</li><li>A modal dialog will appear displaying a short code (e.g., <code>B49X-Y2K9</code>) and a direct link to <code>microsoft.com/link</code>.</li><li>Confirm the login code in your regular web browser with your Microsoft account owning Minecraft Java Edition.</li><li>The launcher automatically detects approval, pulls your custom 3D skin preview, and securely encrypts your tokens using OS-level secure storage.</li></ol><div class="tip custom-block"><p class="custom-block-title">Maximum Security</p><p>Gens Launcher never sees or stores your Microsoft password. Authentication is completed via Microsoft&#39;s official OAuth2 Device Code Flow.</p></div><h3 id="_2-offline-local-player-mode" tabindex="-1">2. Offline / Local Player Mode <a class="header-anchor" href="#_2-offline-local-player-mode" aria-label="Permalink to &quot;2. Offline / Local Player Mode&quot;">​</a></h3><p>If you don&#39;t have an active Internet connection or wish to play on a local area network (LAN):</p><ol><li>Click on the <strong>Offline Mode / Local Username</strong> option.</li><li>Enter your desired player name.</li><li>You can now launch any previously installed instance locally.</li></ol><hr><h2 id="exploring-the-interface" tabindex="-1">Exploring the Interface <a class="header-anchor" href="#exploring-the-interface" aria-label="Permalink to &quot;Exploring the Interface&quot;">​</a></h2><p>The interface of Gens Launcher is organized into 4 main areas:</p><ol><li><strong>Instance Gallery:</strong> Visually displays all your configured game profiles with their Minecraft version, modloader icon, and cloud sync status.</li><li><strong>Launch Action Bar:</strong> Provides a single-click button to start the selected profile. A dynamic progress bar visualizes asset downloads, delta sync patching, and Java startup.</li><li><strong>Content Manager:</strong> Dedicated browser to find and add mods, shaders, and texture packs in one click.</li><li><strong>Settings Panel:</strong> Theme customization, RAM allocation, Java runtime selection, and Cloud Provider connections.</li></ol><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./installation">Multi-OS Installation Guide</a></li><li><a href="./instances-and-mods">Managing Instances and Installing Mods</a></li><li><a href="./cloud-sync">Setting Up Horizon Cloud Sync</a></li><li><a href="./troubleshooting">FAQ and Troubleshooting</a></li></ul>',23)])])}const m=t(r,[["render",i]]);export{h as __pageData,m as default};
